mapper.select:
SELECT B1.* FROM ( SELECT A1.*, ROW_NUMBER() OVER( ORDER BY
A1.insertDt DESC
CAST(A1.${sortColumn} AS INTEGER) ${order}
A1.${sortColumn} ${order}
) AS PAGEINDEX FROM ( SELECT info.*, fileTypes.file_extensions AS fileExtensions, securityGrade.grade_cd AS gradeCd, securityGrade.grade_nm AS gradeNm, securityGrade.grade_level AS gradeLevel, insertUser.USER_NM AS insertUserNm, updateUser.USER_NM AS updateUserNm, ecnInsert.USER_NM AS ecnUserNm FROM (
SELECT info.BUSINESS_TYPE_CD AS businessTypeCd, FN_GET_CD_NM('businessTypeCd', info.BUSINESS_TYPE_CD, 'ko') AS businessTypeNm, info.SW_TYPE_CD AS swTypeCd, FN_GET_CD_NM('swClassCd1', info.SW_TYPE_CD, 'ko') AS swTypeNm, info.DISTRIBUTE_TYPE_CD AS distributeTypeCd, -- FN_GET_CD_NM('distributeTypeCd', info.DISTRIBUTE_TYPE_CD, 'ko') AS distributeTypeNm, info.DISTRIBUTE_TYPE_NAME AS distributeTypeNm, info.SW_NO AS swNo, info.SW_NM AS swNm, info.SW_VERSION_No AS swVersionNo, info.OBJECT_ID AS objectId, info.REV_NO AS revNo, info.INSERT_UID AS insertUid, info.UPDATE_UID AS updateUid, info.ecn_insert_uid AS ecn_insert_uid, info.REGISTER_USER AS registerUser, info.INSERT_DEPT_NM AS insertDeptNm, info.STD_GAPP_DT AS stdGappDt, info.CHANGE_GAPP_DT AS changeGappDt, info.ECN_NO AS ecnNo, info.BUSINESS_AREA_CD AS businessAreaCd, FN_GET_CD_NM('businessAreaCdAll', info.BUSINESS_AREA_CD, 'ko') AS businessAreaNm, info.PROTECT_YN AS protectYn, info.PROTECT_YN AS protectYnView, info.UPDATE_DT AS updateDt, info.INSERT_DT AS insertDt, info.CREATE_DT AS createDt, info.CCBDATE AS ccbDate, info.APPROVER AS approver, info.REVIEWERUSER AS reviewerUser, COALESCE(fileInfo.PROCESSING_STATUS, '') AS processingStatus, CASE WHEN info.STATUS = '승인완료' THEN '승인완료' WHEN COALESCE(NULLIF(TRIM(info.APPROVER), ''), '') <> '' AND NOT EXISTS ( SELECT 1 FROM regexp_split_to_table(REPLACE(info.APPROVER, ' ', ''), ',') AS ap(token) WHERE ap.token <> '' AND POSITION(',' || ap.token || ',' IN ',' || REPLACE(COALESCE(info.APPROVED_USERS, info.STATUS, ''), ' ', '') || ',') = 0 ) AND ( COALESCE(NULLIF(TRIM(info.REVIEWERUSER), ''), '') = '' OR NOT EXISTS ( SELECT 1 FROM regexp_split_to_table(REPLACE(info.REVIEWERUSER, ' ', ''), ',') AS rv(token) WHERE rv.token <> '' AND POSITION(',' || rv.token || ',' IN ',' || REPLACE(COALESCE(info.APPROVED_USERS, info.STATUS, ''), ' ', '') || ',') = 0 ) ) THEN '승인완료' ELSE '승인진행중' END AS status, info.INTERFACE_DT AS interfaceDt, info.PRODUCT_CD AS productCd, COALESCE(info.PRODUCT_CD, '') AS productNm, ( (SELECT COUNT(*) FROM DOCS_SW_FILE swFile WHERE swFile.OBJECT_ID = info.OBJECT_ID) + (SELECT COUNT(*) FROM DOCS_SW_SUB_FILE subFile WHERE subFile.PARENT_OBJECT_ID = info.OBJECT_ID AND COALESCE(subFile.USE_YN, 'Y') = 'Y') ) AS fileCount, DENSE_RANK() OVER (PARTITION BY SW_NO ORDER BY REV_NO DESC) AS rnk, fileInfo.FILE_NO AS fileNo, fileInfo.ORG_FILE_NM AS fileViewNm, fileInfo.FILE_NM AS fileNm, fileInfo.FILE_SIZE AS fileSize, fileInfo.ORG_FILE_NM AS orgFileNm, fileInfo.FILE_PATH_NM AS filePath, info.VALID_TYPE AS validType FROM DOCS_SW_FILE fileInfo JOIN DOCS_SW info ON fileInfo.OBJECT_ID = info.OBJECT_ID
SELECT info.BUSINESS_TYPE_CD AS businessTypeCd, FN_GET_CD_NM('businessTypeCd', info.BUSINESS_TYPE_CD, 'ko') AS businessTypeNm, info.SW_TYPE_CD AS swTypeCd, FN_GET_CD_NM('swClassCd1', info.SW_TYPE_CD, 'ko') AS swTypeNm, info.DISTRIBUTE_TYPE_CD AS distributeTypeCd, -- FN_GET_CD_NM('distributeTypeCd', info.DISTRIBUTE_TYPE_CD, 'ko') AS distributeTypeNm, info.DISTRIBUTE_TYPE_NAME AS distributeTypeNm, info.SW_NO AS swNo, info.SW_NM AS swNm, info.SW_VERSION_No AS swVersionNo, info.OBJECT_ID AS objectId, info.REV_NO AS revNo, info.INSERT_UID AS insertUid, info.UPDATE_UID AS updateUid, info.ecn_insert_uid AS ecn_insert_uid, info.REGISTER_USER AS registerUser, info.INSERT_DEPT_NM AS insertDeptNm, info.STD_GAPP_DT AS stdGappDt, info.CHANGE_GAPP_DT AS changeGappDt, info.ECN_NO AS ecnNo, info.BUSINESS_AREA_CD AS businessAreaCd, FN_GET_CD_NM('businessAreaCdAll', info.BUSINESS_AREA_CD, 'ko') AS businessAreaNm, info.PROTECT_YN AS protectYn, info.PROTECT_YN AS protectYnView, info.UPDATE_DT AS updateDt, info.INSERT_DT AS insertDt, info.CREATE_DT AS createDt, info.CCBDATE AS ccbDate, info.APPROVER AS approver, info.REVIEWERUSER AS reviewerUser, COALESCE(fileInfo.PROCESSING_STATUS, '') AS processingStatus, CASE WHEN info.STATUS = '승인완료' THEN '승인완료' WHEN COALESCE(NULLIF(TRIM(info.APPROVER), ''), '') <> '' AND NOT EXISTS ( SELECT 1 FROM regexp_split_to_table(REPLACE(info.APPROVER, ' ', ''), ',') AS ap(token) WHERE ap.token <> '' AND POSITION(',' || ap.token || ',' IN ',' || REPLACE(COALESCE(info.APPROVED_USERS, info.STATUS, ''), ' ', '') || ',') = 0 ) AND ( COALESCE(NULLIF(TRIM(info.REVIEWERUSER), ''), '') = '' OR NOT EXISTS ( SELECT 1 FROM regexp_split_to_table(REPLACE(info.REVIEWERUSER, ' ', ''), ',') AS rv(token) WHERE rv.token <> '' AND POSITION(',' || rv.token || ',' IN ',' || REPLACE(COALESCE(info.APPROVED_USERS, info.STATUS, ''), ' ', '') || ',') = 0 ) ) THEN '승인완료' ELSE '승인진행중' END AS status, info.INTERFACE_DT AS interfaceDt, info.PRODUCT_CD AS productCd, COALESCE(info.PRODUCT_CD, '') AS productNm, ( (SELECT COUNT(*) FROM DOCS_SW_FILE swFile WHERE swFile.OBJECT_ID = info.OBJECT_ID) + (SELECT COUNT(*) FROM DOCS_SW_SUB_FILE subFile WHERE subFile.PARENT_OBJECT_ID = info.OBJECT_ID AND COALESCE(subFile.USE_YN, 'Y') = 'Y') ) AS fileCount, fileInfo.FILE_NO AS fileNo, fileInfo.ORG_FILE_NM AS fileViewNm, fileInfo.FILE_NM AS fileNm, fileInfo.FILE_SIZE AS fileSize, fileInfo.ORG_FILE_NM AS orgFileNm, fileInfo.FILE_PATH_NM AS filePath, info.VALID_TYPE AS validType FROM DOCS_SW_FILE fileInfo JOIN DOCS_SW info ON fileInfo.OBJECT_ID = info.OBJECT_ID
WHERE 1=1 AND info.DELETED_YN = 'N'
AND BUSINESS_TYPE_CD = #{businessTypeCd}
AND BUSINESS_AREA_CD LIKE '%' || #{businessAreaCd} || '%'
AND SW_NO = UPPER(TRIM(#{swNo}))
AND SW_NO LIKE '%' || UPPER(TRIM(#{swNo})) || '%'
AND EXISTS ( SELECT 1 FROM DOCS_SW_TREE node JOIN DOCS_SW_TREE selectedNode ON selectedNode.TREE_CD IN
#{treeCd}
WHERE node.TREE_CD = info.TREE_CD AND node.TREE_PATH LIKE selectedNode.TREE_PATH || '%' )
AND info.SW_NM LIKE '%' || #{swNm} || '%'
AND ( fileInfo.ORG_FILE_NM LIKE '%' || #{fileViewNm} || '%' OR fileInfo.FILE_NM LIKE '%' || #{fileViewNm} || '%' )
AND fileInfo.FILE_NM LIKE '%' || #{fileNm} || '%'
AND SW_TYPE_CD LIKE '%' || #{swTypeCd} || '%'
AND info.DISTRIBUTE_TYPE_CD = #{distributeTypeCd}
AND ECN_NO LIKE '%' || UPPER(TRIM(#{ecnNo})) || '%'
AND PRODUCT_CD = #{productCd}
AND INSERT_UID = #{insertUid}
AND VALID_TYPE IS NULL
AND VALID_TYPE = 'N'
AND info.INTERFACE_DT BETWEEN TO_DATE(#{interfaceStartDt}, 'YYYY-MM-DD') AND TO_DATE(#{interfaceEndDt}, 'YYYY-MM-DD') + INTERVAL '1 DAY'
AND (
(SW_NO LIKE '%' || UPPER(TRIM(#{swInfo.swNo})) || '%')
)
AND (
(SW_NO = UPPER(TRIM(#{swInfo.swNo})))
)
) info LEFT JOIN DOCS_USER insertUser ON insertUser.USER_ID = info.insertUid LEFT JOIN DOCS_USER updateUser ON updateUser.USER_ID = info.updateUid LEFT JOIN DOCS_USER ecnInsert ON ecnInsert.USER_ID = info.ecn_insert_uid LEFT JOIN LATERAL ( SELECT STRING_AGG(extension.file_extension, ', ' ORDER BY extension.file_extension) AS file_extensions FROM ( SELECT DISTINCT UPPER(SUBSTRING(TRIM(accessibleFile.org_file_nm) FROM '[.]([^.]+)$')) AS file_extension FROM ( SELECT 'SW'::varchar AS object_type, mainFile.FILE_NO::varchar AS file_no, mainFile.ORG_FILE_NM AS org_file_nm FROM DOCS_SW_FILE mainFile WHERE mainFile.OBJECT_ID = info.objectId UNION ALL SELECT 'SW_SUB'::varchar AS object_type, subFile.FILE_NO::varchar AS file_no, subFile.ORG_FILE_NM AS org_file_nm FROM DOCS_SW_SUB_FILE subFile WHERE subFile.PARENT_OBJECT_ID = info.objectId AND COALESCE(subFile.USE_YN, 'Y') = 'Y' ) accessibleFile JOIN DOCS_USER extensionActor ON extensionActor.USER_CD = #{aclUserCd} AND extensionActor.USE_YN = 'Y' AND extensionActor.DEL_YN = 'N' AND COALESCE(extensionActor.LOCK_YN, 'N') != 'Y' JOIN DOCS_USER_SECURITY_CLEARANCE extensionClearance ON extensionClearance.USER_CD = extensionActor.USER_CD AND extensionClearance.VALID_FROM <= CURRENT_TIMESTAMP AND (extensionClearance.VALID_TO IS NULL OR extensionClearance.VALID_TO > CURRENT_TIMESTAMP) JOIN DOCS_SECURITY_GRADE extensionUserGrade ON extensionUserGrade.GRADE_CD = extensionClearance.GRADE_CD AND extensionUserGrade.USE_YN = 'Y' JOIN DOCS_USER_ACTION_PERMISSION extensionActionPermission ON extensionActionPermission.USER_CD = extensionActor.USER_CD AND extensionActionPermission.ACTION_CD = 'VIEW' AND extensionActionPermission.ALLOW_YN = 'Y' JOIN DOCS_OBJECT_USER_PERMISSION extensionObjectPermission ON extensionObjectPermission.OBJECT_TYPE = 'SW' AND extensionObjectPermission.OBJECT_ID = info.objectId AND extensionObjectPermission.USER_CD = extensionActor.USER_CD AND extensionObjectPermission.ACTION_CD = 'VIEW' AND extensionObjectPermission.ALLOW_YN = 'Y' JOIN LATERAL ( SELECT extensionLabel.GRADE_CD FROM DOCS_FILE_SECURITY_LABEL extensionLabel LEFT JOIN DOCS_SECURITY_GRADE extensionCandidateGrade ON extensionCandidateGrade.GRADE_CD = extensionLabel.GRADE_CD WHERE extensionLabel.OBJECT_ID = info.objectId AND ( ( extensionLabel.OBJECT_TYPE = accessibleFile.object_type AND extensionLabel.FILE_NO IN (accessibleFile.file_no, '*') ) OR ( accessibleFile.object_type = 'SW_SUB' AND extensionLabel.OBJECT_TYPE = 'SW' AND extensionLabel.FILE_NO = '*' ) ) ORDER BY extensionCandidateGrade.GRADE_LEVEL DESC NULLS LAST, CASE WHEN extensionLabel.OBJECT_TYPE = accessibleFile.object_type AND extensionLabel.FILE_NO = accessibleFile.file_no THEN 0 WHEN extensionLabel.OBJECT_TYPE = accessibleFile.object_type AND extensionLabel.FILE_NO = '*' THEN 1 ELSE 2 END LIMIT 1 ) effectiveExtensionLabel ON TRUE JOIN DOCS_SECURITY_GRADE extensionFileGrade ON extensionFileGrade.GRADE_CD = effectiveExtensionLabel.GRADE_CD AND extensionFileGrade.USE_YN = 'Y' WHERE extensionUserGrade.GRADE_LEVEL >= extensionFileGrade.GRADE_LEVEL ) extension WHERE extension.file_extension IS NOT NULL AND extension.file_extension != '' ) fileTypes ON TRUE LEFT JOIN LATERAL ( SELECT label.grade_cd, grade.grade_nm, grade.grade_level FROM docs_file_security_label label LEFT JOIN docs_security_grade grade ON grade.grade_cd = label.grade_cd WHERE label.object_type = 'SW' AND label.object_id = info.objectId AND label.file_no IN (CAST(info.fileNo AS TEXT), '*') ORDER BY grade.grade_level DESC NULLS LAST, CASE WHEN label.file_no = CAST(info.fileNo AS TEXT) THEN 0 ELSE 1 END LIMIT 1 ) securityGrade ON TRUE
WHERE rnk = 1
ORDER BY insertDT DESC, swNo, revNo DESC, fileNo
ORDER BY ${sortColumn} ${order}
) A1 ) B1 WHERE 1=1
AND PAGEINDEX <= #{end}
AND PAGEINDEX >= #{start}

SELECT OBJECT_ID
FROM DOCS_SW_FILE
WHERE OBJECT_ID = #{objectId}

mapper.update:
UPDATE DOCS_SW SET
DELETED_YN = 'Y'
WHERE OBJECT_ID = #{objectId}

mapper.select:
SELECT mainFile.OBJECT_ID AS "objectId", CAST(mainFile.FILE_NO AS TEXT) AS "fileNo", mainFile.ORG_FILE_NM AS "orgFileNm", mainFile.FILE_PATH_NM AS "filePath", 'SW' AS "aclObjectType", mainFile.OBJECT_ID AS "aclObjectId" FROM DOCS_SW_FILE mainFile JOIN DOCS_SW sw ON sw.OBJECT_ID = mainFile.OBJECT_ID WHERE mainFile.OBJECT_ID = #{objectId} AND COALESCE(sw.DELETED_YN, 'N') = 'N' AND CAST(mainFile.FILE_NO AS INTEGER) = 1
AND CAST(mainFile.FILE_NO AS TEXT) = #{fileNo}
UNION ALL SELECT subFile.OBJECT_ID AS "objectId", CAST(subFile.FILE_NO AS TEXT) AS "fileNo", subFile.ORG_FILE_NM AS "orgFileNm", subFile.FILE_PATH_NM AS "filePath", 'SW_SUB' AS "aclObjectType", subFile.PARENT_OBJECT_ID AS "aclObjectId" FROM DOCS_SW_SUB_FILE subFile WHERE (subFile.OBJECT_ID = #{objectId} OR subFile.PARENT_OBJECT_ID = #{objectId}) AND COALESCE(subFile.USE_YN, 'Y') = 'Y'
AND CAST(subFile.FILE_NO AS TEXT) = #{fileNo}
LIMIT 1
